/* Also embedded verbatim in standalone exports; no network dependencies. */
function paperPlayer(P,coreFactory,effectFactory){const C=coreFactory(),F=effectFactory(),E=id=>document.getElementById(id);let i=0,trail=[],cancelEffect=()=>{};function draw(animate=false){cancelEffect();const n=P.nodes[i];E('layers').replaceChildren();if(!n){E('text').textContent='暂无剧情';return}for(const l of C.scene(P,n.id,trail)){if(l.hidden)continue;const a=P.assets.find(a=>a.id===l.asset);if(!a)continue;const wrap=document.createElement('div');wrap.className='visual-layer';wrap.dataset.layer=l.id;Object.assign(wrap.style,{left:l.x+'%',top:l.y+'%',width:l.w+'%',height:l.h+'%',opacity:l.opacity/100});const im=document.createElement('img');im.alt=l.name;im.src=a.data;im.className=l.motion;im.style.objectFit=l.fit;wrap.appendChild(im);E('layers').appendChild(wrap)}E('who').textContent=n.name||'';E('text').textContent=n.text;E('choices').replaceChildren();if(n.type==='choice')for(const o of n.options){const b=document.createElement('button');b.textContent=o.text;b.onclick=e=>{e.stopPropagation();go(o.target)};E('choices').appendChild(b)}E('hint').textContent=n.type==='end'?'故事结束':n.type==='choice'?'请选择一个选项':'点击 / 空格继续 ▸';E('back').disabled=!trail.length;const ls=C.scene(P,n.id,trail);if(animate)cancelEffect=F.animate(P,C,n.id,trail,E('layers'),ls);else F.apply(E('layers'),ls,F.frame(P,C,n.id,trail));}
function go(target){const j=P.nodes.findIndex(n=>n.id===target);if(j>=0){trail.push(P.nodes[i].id);i=j;draw(true)}}function next(){const n=P.nodes[i];if(n?.type==='say')go(n.next||P.nodes[i+1]?.id)}E('scene').onclick=next;document.onkeydown=e=>{if(e.target.tagName==='BUTTON')return;if(e.key===' '||e.key==='Enter'){e.preventDefault();next()}};E('restart').onclick=()=>{i=0;trail=[];draw(true)};E('back').onclick=()=>{if(trail.length){const at=trail.pop();i=P.nodes.findIndex(n=>n.id===at);draw()}};const key='paper-game-'+P.id;E('save').onclick=()=>{try{localStorage.setItem(key,JSON.stringify({id:P.nodes[i]?.id,trail}));E('msg').textContent='进度已保存'}catch{E('msg').textContent='浏览器不允许保存'}};E('load').onclick=()=>{try{const x=JSON.parse(localStorage.getItem(key));if(x&&P.nodes.some(n=>n.id===x.id)&&Array.isArray(x.trail)&&x.trail.every(t=>P.nodes.some(n=>n.id===t))){i=P.nodes.findIndex(n=>n.id===x.id);trail=x.trail;draw();E('msg').textContent='已读取进度'}else E('msg').textContent='没有有效存档'}catch{E('msg').textContent='无法读取存档'}};E('title').textContent=P.title;draw(true)}
const paperPlayerCSS=`body{margin:0;background:#17261f;color:#f3f5eb;font:16px/1.8 "Microsoft YaHei",sans-serif;display:flex;min-height:100vh;align-items:center;justify-content:center;flex-direction:column}h1{font-size:18px;font-weight:400}#scene{width:min(1100px,96vw);aspect-ratio:16/9;position:relative;overflow:hidden;background:#dfe7dd;border-radius:8px;cursor:pointer}#layers{position:absolute;inset:0;pointer-events:none}.visual-layer{position:absolute}.visual-layer img{width:100%;height:100%;display:block;transform-origin:bottom center}.breathe{animation:b 4s ease-in-out infinite}.sway{animation:s 5s ease-in-out infinite}@keyframes b{50%{transform:scaleY(1.017)}}@keyframes s{0%,100%{transform:rotate(-1deg)}50%{transform:rotate(1deg)}}#box{position:absolute;bottom:5%;left:5%;right:5%;padding:clamp(8px,2vw,18px) clamp(12px,2vw,22px);background:#fbfff1ed;color:#273d35;border-radius:6px;font-size:clamp(11px,1.6vw,18px)}#who{font-weight:bold;color:#3f6753}#text{white-space:pre-wrap;overflow-wrap:anywhere}#hint{font-size:10px;text-align:right;color:#76876c}#choices{position:absolute;top:10%;left:20%;right:20%;display:grid;gap:6px}button{font:inherit;font-size:clamp(10px,1.3vw,14px);background:#f3f5eb;color:#273d35;border:1px solid #b7c2ad;border-radius:5px;padding:6px 12px;cursor:pointer}button:disabled{opacity:.4}nav{display:flex;gap:8px;margin-top:16px;flex-wrap:wrap}#msg{font-size:12px;min-height:24px}@media(prefers-reduced-motion:reduce){*{animation:none!important}}`;
if(typeof module!=='undefined')module.exports={paperPlayer,paperPlayerCSS};
